import json
f = "90a099ea-a2b0-4eab-9ec2-2d23bfb8a64f.jsonl"
lines = open(f).readlines()

def find_tool_use_for(idx):
    obj = json.loads(lines[idx])
    parent = obj.get("parentUuid")
    # search backwards for assistant message with tool_use matching parent uuid == this message's uuid? Actually tool_result's parentUuid points to the assistant tool_use message uuid typically same line before.
    for j in range(idx-1, max(0, idx-5), -1):
        o2 = json.loads(lines[j])
        if o2.get("uuid") == parent:
            return o2
    return None

count_images = 0
total_bytes = 0
tool_names = {}
for i, line in enumerate(lines):
    obj = json.loads(line)
    tur = obj.get("toolUseResult")
    if isinstance(tur, dict) and tur.get("type") == "image":
        count_images += 1
        total_bytes += len(line)
        prev = find_tool_use_for(i)
        if prev:
            msg = prev.get("message", {})
            content = msg.get("content")
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get("type") == "tool_use":
                        name = c.get("name")
                        inp = c.get("input", {})
                        fp = inp.get("file_path") or inp.get("path")
                        tool_names.setdefault(name, []).append(fp)
print("image tool_results:", count_images, "total bytes:", total_bytes)
for name, paths in tool_names.items():
    print(name, len(paths))
    for p in paths[:20]:
        print("   ", p)
